"use client";

import { useMemo, useState } from "react";
import {
  Area,
  Bar,
  BarChart,
  CartesianGrid,
  Cell,
  ComposedChart,
  Legend,
  Line,
  ResponsiveContainer,
  Scatter,
  ScatterChart,
  XAxis,
  YAxis,
  ZAxis,
} from "recharts";
import { Tooltip } from "@/components/charts/SortedTooltip";
import {
  CENTER_STOCK_PATH,
  HEADLINE,
  NEW_VS_STOCK_BANDS,
  OPENINGS_BY_COHORT,
  POVERTY_QUINTILES,
  SOURCE_NOTE,
  STATE_DENSITY,
  TRACT_CONTRAST,
  fmt1,
  fmtInt,
  statesByDensity,
} from "@/data/plasma-center-density-vs-poverty-2026-data";

// viz-types: quintile density bars, new-vs-stock grouped bars, state poverty??density scatter,
// stock path area+line, tract contrast bars, cohort density composed | layout: default

type ViewId = "density" | "openings" | "states" | "context";
type RegionFilter = "all" | "South" | "West" | "Midwest" | "Northeast";
type DensityMetric = "centersPer100k" | "locationIndex" | "centerSharePct";

const NAVY = "#0f172a";
const TEAL = "#0d9488";
const AMBER = "#d97706";
const ROSE = "#e11d48";
const SLATE = "#64748b";
const INDIGO = "#4f46e5";
const SKY = "#0284c8";

const REGION_COLORS: Record<string, string> = {
  South: ROSE,
  West: TEAL,
  Midwest: INDIGO,
  Northeast: AMBER,
};

const Q_COLORS = [SKY, TEAL, SLATE, AMBER, ROSE];

function ChartCard({
  title,
  subtitle,
  children,
}: {
  title: string;
  subtitle?: string;
  children: React.ReactNode;
}) {
  return (
    <div className="w-full min-w-0 overflow-hidden rounded-xl border border-slate-200 bg-white shadow-sm">
      <div className="border-b border-slate-100 bg-slate-50 px-5 py-4">
        <h3 className="text-lg font-bold text-slate-900">{title}</h3>
        {subtitle && <p className="mt-1 text-sm text-slate-500">{subtitle}</p>}
      </div>
      <div className="p-4 sm:p-6">{children}</div>
    </div>
  );
}

function ToggleGroup<T extends string>({
  label,
  value,
  options,
  onChange,
}: {
  label: string;
  value: T;
  options: { id: T; label: string }[];
  onChange: (v: T) => void;
}) {
  return (
    <div className="flex flex-wrap items-center gap-2">
      <span className="text-xs font-semibold uppercase tracking-wide text-slate-500">
        {label}
      </span>
      <div className="inline-flex flex-wrap rounded-lg border border-slate-200 bg-white p-0.5">
        {options.map((o) => (
          <button
            key={o.id}
            type="button"
            onClick={() => onChange(o.id)}
            className={`rounded-md px-3 py-1.5 text-sm font-medium transition-colors ${
              value === o.id
                ? "bg-slate-900 text-white"
                : "text-slate-600 hover:bg-slate-50"
            }`}
          >
            {o.label}
          </button>
        ))}
      </div>
    </div>
  );
}

export function PlasmaCenterDensityVsPoverty2026Dashboard() {
  const [view, setView] = useState<ViewId>("density");
  const [region, setRegion] = useState<RegionFilter>("all");
  const [metric, setMetric] = useState<DensityMetric>("centersPer100k");

  const quintileBars = useMemo(() => {
    return POVERTY_QUINTILES.map((q, i) => ({
      name: q.label.replace(" poverty", ""),
      band: q.povertyBand,
      value:
        metric === "centersPer100k"
          ? q.centersPer100k
          : metric === "locationIndex"
            ? q.locationIndex
            : q.centerSharePct,
      fill: Q_COLORS[i],
      adultsM: q.adultsM,
      centers: q.centers,
    }));
  }, [metric]);

  const newVsStock = useMemo(
    () =>
      NEW_VS_STOCK_BANDS.map((b) => ({
        name: b.label,
        New: b.newSharePct,
        Stock: b.stockSharePct,
        Adults: b.adultSharePct,
        band: b.povertyBand,
      })),
    [],
