                  <YAxis
                    yAxisId="pop"
                    orientation="right"
                    domain={[0, 30]}
                    tick={{ fontSize: 11 }}
                    hide
                  />
                  <Tooltip />
                  <Legend />
                  <Bar
                    yAxisId="idx"
                    dataKey="index"
                    name="Location index"
                    radius={[4, 4, 0, 0]}
                  >
                    {POVERTY_QUINTILES.map((_, i) => (
                      <Cell key={i} fill={Q_COLORS[i]} />
                    ))}
                  </Bar>
                  <Line
                    yAxisId="idx"
                    type="monotone"
                    dataKey={() => 1}
                    name="Proportional (1.0)"
                    stroke={NAVY}
                    strokeDasharray="4 4"
                    dot={false}
                    legendType="none"
                  />
                </ComposedChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>
        </div>
      )}

      {view === "openings" && (
        <div className="grid gap-6 lg:grid-cols-2">
          <ChartCard
            title="New openings vs existing stock"
            subtitle="% of sites by ZCTA poverty band ?? 2021???25 openings vs pre-2021 stock"
          >
            <div className="h-80 w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart data={newVsStock} margin={{ left: 8, right: 8 }}>
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis dataKey="name" tick={{ fontSize: 11 }} />
                  <YAxis
                    tick={{ fontSize: 11 }}
                    unit="%"
                    domain={[0, 45]}
                  />
                  <Tooltip />
                  <Legend />
                  <Bar dataKey="New" fill={ROSE} radius={[3, 3, 0, 0]} />
                  <Bar dataKey="Stock" fill={SLATE} radius={[3, 3, 0, 0]} />
                  <Bar dataKey="Adults" fill={TEAL} radius={[3, 3, 0, 0]} />
                </BarChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>

          <ChartCard
            title="Density by opening cohort"
            subtitle="Centers per 100k adults in high- vs low-poverty ZCTAs"
          >
            <div className="h-80 w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <ComposedChart data={cohortBars} margin={{ left: 8, right: 8 }}>
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis dataKey="name" tick={{ fontSize: 10 }} />
                  <YAxis tick={{ fontSize: 11 }} />
                  <Tooltip />
                  <Legend />
                  <Bar
                    dataKey="High"
                    name="High-poverty density"
                    fill={ROSE}
                    radius={[3, 3, 0, 0]}
                  />
                  <Bar
                    dataKey="Low"
                    name="Low-poverty density"
                    fill={SKY}
                    radius={[3, 3, 0, 0]}
                  />
                  <Line
                    type="monotone"
                    dataKey="share"
                    name="High-poverty share %"
                    stroke={AMBER}
                    strokeWidth={2}
                    yAxisId={0}
                  />
                </ComposedChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>
        </div>
      )}

      {view === "states" && (
        <div className="grid gap-6 lg:grid-cols-2">
          <ChartCard
            title="Poverty rate ?? centers per 100k adults"
            subtitle="Selected states ?? bubble size = center count"
          >
            <div className="h-80 w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <ScatterChart margin={{ left: 8, right: 16, top: 8, bottom: 8 }}>
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis
                    type="number"
                    dataKey="x"
                    name="Poverty %"
                    unit="%"
                    tick={{ fontSize: 11 }}
                    domain={[8, 20]}
                    label={{
                      value: "ACS poverty %",
                      position: "insideBottom",
                      offset: -2,
                      fontSize: 11,
                    }}
                  />
                  <YAxis
                    type="number"
                    dataKey="y"
                    name="Density"
                    tick={{ fontSize: 11 }}
                    domain={[0, 1.1]}
                    label={{
                      value: "Centers / 100k",
                      angle: -90,
                      position: "insideLeft",
                      fontSize: 11,
                    }}
                  />
                  <ZAxis type="number" dataKey="z" range={[40, 280]} />
                  <Tooltip
                    cursor={{ strokeDasharray: "3 3" }}
                    formatter={(v, name) => {
                      if (name === "x") return [`${fmt1(Number(v))}%`, "Poverty"];
                      if (name === "y")
                        return [fmt1(Number(v)), "Per 100k adults"];
                      if (name === "z") return [fmtInt(Number(v)), "Centers"];
                      return [String(v), String(name)];
                    }}
                    labelFormatter={(_, payload) => {
                      const p = payload?.[0]?.payload as
                        | { abbr?: string; state?: string }
                        | undefined;
                      return p?.state ?? p?.abbr ?? "";
                    }}
                  />
                  <Scatter data={stateScatter} name="States">
                    {stateScatter.map((d) => (
                      <Cell key={d.abbr} fill={d.fill} />
                    ))}
                  </Scatter>
                </ScatterChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>

          <ChartCard
            title="Centers per 100k adults by state"
            subtitle={
              region === "all" ? "All selected states" : `${region} only`
            }
          >
            <div className="h-80 w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart
                  data={stateRank}
                  layout="vertical"
                  margin={{ left: 8, right: 16 }}
                >
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis type="number" tick={{ fontSize: 11 }} />
                  <YAxis
                    type="category"
                    dataKey="name"
                    width={36}
                    tick={{ fontSize: 11 }}
                  />
                  <Tooltip
                    formatter={(v) => [fmt1(Number(v)), "Per 100k"]}
                  />
                  <Bar dataKey="value" radius={[0, 4, 4, 0]}>
                    {stateRank.map((d) => (
                      <Cell key={d.name} fill={d.fill} />
                    ))}
                  </Bar>
                </BarChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>
        </div>
      )}

      {view === "context" && (
        <div className="grid gap-6 lg:grid-cols-2">
          <ChartCard
            title="US plasma center stock"
            subtitle="FDA / industry published points ?? 2005???2025"
          >
            <div className="h-80 w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <ComposedChart data={stockPath} margin={{ left: 8, right: 8 }}>
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis dataKey="year" tick={{ fontSize: 11 }} />
                  <YAxis tick={{ fontSize: 11 }} />
                  <Tooltip
                    formatter={(v) =>
                      typeof v === "number" ? fmtInt(v) : String(v)
                    }
                  />
                  <Area
                    type="monotone"
                    dataKey="centers"
                    fill={`${ROSE}33`}
                    stroke={ROSE}
                    strokeWidth={2}
                    name="Centers"
                  />
                  <Line
                    type="monotone"
                    dataKey="centers"
                    stroke={NAVY}
                    strokeWidth={0}
                    dot={{ r: 3, fill: NAVY }}
                    legendType="none"
                  />
                </ComposedChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>

          <ChartCard
            title="Census tracts with vs without a center"
            subtitle="Means ?? May 2017 FDA set ?? ACS 2011???15 (Michigan study)"
          >
            <div className="h-80 w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart data={tractBars} margin={{ left: 8, right: 8 }}>
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis dataKey="name" tick={{ fontSize: 9 }} interval={0} />
                  <YAxis tick={{ fontSize: 11 }} unit="%" />
                  <Tooltip />
                  <Legend />
                  <Bar
                    dataKey="Without"
                    name="No center"
                    fill={SLATE}
                    radius={[3, 3, 0, 0]}
                  />
                  <Bar
                    dataKey="With"
                    name="Has center"
                    fill={ROSE}
                    radius={[3, 3, 0, 0]}
                  />
                </BarChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>
        </div>
      )}

      <p className="text-xs leading-relaxed text-slate-500">{SOURCE_NOTE}</p>
    </div>
  );
}

