import fs from "node:fs";

const p = "src/data/posts.ts";
let s = fs.readFileSync(p, "utf8");
const start = s.indexOf('id: "plasma-center-density-vs-poverty-2026"');
const end = s.indexOf(
  'id: "us-work-stoppage-idleness-versus-union-density-2026"',
);
if (start < 0 || end < 0) throw new Error("bounds not found");

let chunk = s.slice(start, end);
chunk = chunk
  .replace(/1\.9A-/g, "1.9x")
  .replace(/\uFFFD\?+/g, "-")
  .replace(/\uFFFD%?\uFFFD/g, ">=")
  .replace(/\uFFFD/g, "-")
  .replace(/???/g, "-")
  .replace(/???/g, "-")
  .replace(/??/g, "x")
  .replace(/???/g, ">=")
  .replace(/???/g, "~");

// Ensure hero path matches shipped asset
chunk = chunk.replace(
  /imageUrl:\s*\n\s*"[^"]*plasma-center-density-vs-poverty-2026[^"]*"/,
  'imageUrl:\n      "/images/global-systems-plasma-center-density-vs-poverty-2026-hero.png"',
);

s = s.slice(0, start) + chunk + s.slice(end);
fs.writeFileSync(p, s, "utf8");
console.log("fixed");
console.log(s.slice(start, start + 520));

