import { chromium } from 'playwright';
import { startStaticServer, stopStaticServer } from './scripts/lib/static-server.mjs';
const port = 4180;
const server = await startStaticServer('out', port);
const browser = await chromium.launch({ headless: true });
const page = await browser.newPage();
page.on('pageerror', e => console.log('PAGEERROR', e.message));
page.on('console', m => { if (m.type()==='error') console.log('CONSOLE', m.text()); });
await page.goto('http://127.0.0.1:'+port+'/blog/plasma-center-density-vs-poverty-2026.html', { waitUntil: 'networkidle', timeout: 60000 });
await page.waitForTimeout(3000);
const text = await page.locator('body').innerText();
console.log('HAS_MARKER', text.includes('Plasma'));
console.log('HAS_DENSITY', text.includes('density'));
console.log('SNIP', text.slice(0, 500));
const viz = await page.locator('[data-viz]').count();
console.log('data-viz count', viz);
await browser.close();
await stopStaticServer(server);
"

